double sign = (n % 2 == 0) ? 1.0 : -1.0;
double factor = sign / std::acos(-1.0);

double log_factorial = 0.0;
for (size_t i = 1; i <= n; ++i) log_factorial += std::log(i);
for (size_t i = 1; i <= n + k; ++i) log_factorial -= std::log(i);
factor *= std::exp(0.5 * log_factorial);

factor *= std::exp(-2.0 * r * r);
factor *= std::pow(2.0 * r, static_cast<double>(k));

double x = 4.0 * r * r;
double laguerre = 0.0;
for (size_t m = 0; m <= n; ++m) {
    double term = 1.0;
    for (size_t i = 1; i <= m; ++i) term *= static_cast<double>(n + k + i) / i;
    term *= std::pow(-x, static_cast<double>(m)) / std::tgamma(m + 1);
    laguerre += term;
}
factor *= laguerre;

return factor;
// END_CODE

